// Summarize the failed execution for LendLoop. Only metadata + the error
// message are forwarded — never the failed run's input data.
const e = $json;
const failure = e.execution || e.trigger || {};
const payload = {
  workflowId: String((e.workflow && e.workflow.id) || 'unknown'),
  workflowName: String((e.workflow && e.workflow.name) || 'unknown'),
  executionId: String((e.execution && e.execution.id) || 'trigger-' + Date.now()),
  message: String((failure.error && failure.error.message) || 'Unknown error').slice(0, 500),
};
if (e.execution && e.execution.lastNodeExecuted) payload.lastNodeExecuted = String(e.execution.lastNodeExecuted);
if (e.execution && e.execution.url) payload.executionUrl = String(e.execution.url);
return [{ json: { payload } }];

// Sign each outgoing payload for LendLoop (HMAC-SHA256 over "<timestamp>.<body>").
// The secret comes from the n8n environment, never from the workflow JSON.
const crypto = require('crypto');
const secret = $env.N8N_TO_LENDLOOP_SECRET;
if (!secret) throw new Error('N8N_TO_LENDLOOP_SECRET is not configured');

return $input.all().map((item) => {
  const body = JSON.stringify(item.json.payload);
  const timestamp = String(Date.now());
  const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');
  return { json: { body, timestamp, signature }, pairedItem: item.pairedItem };
});

const p = $json.payload;
return [{
  json: {
    to: $env.LENDLOOP_OPS_EMAIL,
    subject: '[LendLoop] n8n workflow failed: ' + p.workflowName,
    text: 'Workflow: ' + p.workflowName + '\nExecution: ' + p.executionId + (p.executionUrl ? ' (' + p.executionUrl + ')' : '') +
      '\nFailed at: ' + (p.lastNodeExecuted || 'n/a') + '\nError: ' + p.message,
  },
}];
